const std = @import("std");
fn clearFirst(items: []u8) void {
    if (items.len > 0) items[0] = 0;
}
fn total(items: []const u8) u32 {
    var sum: u32 = 0;
    for (items) |item| sum += item;
    return sum;
}
fn tail(items: []u8) []u8 {
    return if (items.len == 0) items else items[1..];
}
test "elements and descriptor are separate" {
    var data: [3]u8 = .{ 4, 5, 6 };
    const view: []u8 = &data;
    clearFirst(view);
    const rest: []u8 = tail(view);
    try std.testing.expect(data[0] == 0);
    try std.testing.expect(view.len == 3 and rest.len == 2);
    try std.testing.expect(total(rest) == 11);
}

