defmodule CountSetting do
  def read(settings) do
    with {:ok, text} when is_binary(text) <- Map.fetch(settings, :count),
         {number, ""} <- Integer.parse(text) do
      {:ok, number}
    else
      :error -> {:error, :missing_or_unparseable}
      {:ok, _non_text} -> {:error, :expected_text}
      {_number, _remainder} -> {:error, :trailing_text}
    end
  end
end

defmodule WynReference11Test do
  use ExUnit.Case, async: false

  test "lookup and parse a complete integer" do
    assert CountSetting.read(%{count: "12"}) == {:ok, 12}
    assert CountSetting.read(%{}) == {:error, :missing_or_unparseable}
    assert CountSetting.read(%{count: "many"}) == {:error, :missing_or_unparseable}
    assert CountSetting.read(%{count: 12}) == {:error, :expected_text}
    assert CountSetting.read(%{count: "12 chairs"}) == {:error, :trailing_text}
  end
end

