defmodule ReadingQueue do
  use GenServer
  def start_link(items), do: GenServer.start_link(__MODULE__, items)
  def add(pid, title), do: GenServer.call(pid, {:add, title})
  def items(pid), do: GenServer.call(pid, :items)
  @impl true
  def init(items), do: {:ok, items}
  @impl true
  def handle_call({:add, title}, _from, items) do
    {:reply, :ok, [title | items]}
  end
  def handle_call(:items, _from, items) do
    {:reply, Enum.reverse(items), items}
  end
end

defmodule WynReference16Test do
  use ExUnit.Case, async: false

  test "a small shared reading queue" do
    pid = start_supervised!({ReadingQueue, []})
    assert ReadingQueue.add(pid, "Dune") == :ok
    assert ReadingQueue.add(pid, "Foundation") == :ok
    assert ReadingQueue.items(pid) == ["Dune", "Foundation"]
    assert Process.alive?(pid)
  end
end

