import numpy as np
feature_names = ("temperature_c", "leaf_grams")
saved_mean = np.array([80., 2.])
saved_scale = np.array([10., 1.])
saved_weights = np.array([0.5, -0.25])
saved_bias = 3.0
def predict_one(record):
    if set(record) != set(feature_names):
        raise ValueError("expected temperature_c and leaf_grams")
    values = np.array([record[name] for name in feature_names], dtype=float)
    if values.shape != (2,) or not np.isfinite(values).all():
        raise ValueError("expected two finite scalar numbers")
    prepared = (values - saved_mean) / saved_scale
    return float(prepared @ saved_weights + saved_bias)
assert np.isclose(predict_one({"leaf_grams": 3., "temperature_c": 90.}), 3.25)
try:
    predict_one({"temperature_c": float("nan"), "leaf_grams": 2.})
except ValueError:
    pass
else:
    raise AssertionError("non-finite input was accepted")

struct Countdown(u8);
impl Iterator for Countdown {
    type Item = u8;
    fn next(&mut self) -> Option<Self::Item> {
        if self.0 == 0 { None }
        else { let value = self.0; self.0 -= 1; Some(value) }
    }
}
fn main() {
    let values: Vec<u8> = Countdown(3).collect();
    assert_eq!(values, vec![3, 2, 1]);
}

