static int parse_count(const char *text, int *out) {
    char *end = NULL;
    errno = 0;
    long value = strtol(text, &end, 10);
    if (end == text || *end != '\0' || errno == ERANGE || value < 0 || value > INT_MAX)
        return 0;
    *out = (int)value;
    return 1;
}
int main(void) {
    int value = 0;
    assert(parse_count("42", &value) && value == 42);
    assert(!parse_count("12x", &value));
    assert(!parse_count("", &value));
    assert(!parse_count("-1", &value));
    assert(!parse_count("9999999999999999999999999", &value));
    return 0;
}

