fn main() {
    let original = String::from("tea");
    let mut edited = original.clone(); // a new owned buffer
    edited.push_str(" with mint");
    assert_eq!(original, "tea");
    assert_eq!(edited, "tea with mint");
    let moved = edited; // transfers edited's ownership, no clone here
    assert_eq!(moved, "tea with mint");
}

fn sum(values: &[i32]) -> i32 {
    values.iter().sum()
}
fn main() {
    let array: [i32; 3] = [7, 2, 9];
    let vector: Vec<i32> = vec![4, 6];
    let left: &[i32] = &array;
    let same_data: &[i32] = &array;
    assert_eq!(sum(left), 18);
    assert_eq!(sum(same_data), 18);
    assert_eq!(sum(&vector), 10);
    assert_eq!(sum(&[]), 0); // empty input is valid
    assert_eq!(vector.len(), 2); // ownership was not transferred
}

fn main() {
    let mut values = [10, 20, 30, 40];
    {
        let (left, right) = values.split_at_mut(2);
        left[0] += 1;
        right[0] += 2;
        assert_eq!(left, &[11, 20]);
        assert_eq!(right, &[32, 40]);
    } // these borrows are no longer used
    assert_eq!(values, [11, 20, 32, 40]);
}

fn value_after<'a>(line: &'a str, expected_key: &str) -> Option<&'a str> {
    let (key, value) = line.split_once('=')?;
    if key == expected_key { Some(value) } else { None }
}
fn main() {
    let line = String::from("color=blue");
    let value: Option<&str> = value_after(&line, "color");
    assert_eq!(value, Some("blue"));
    assert_eq!(value_after(&line, "size"), None);
    assert_eq!(value_after("bad line", "color"), None);
}

fn main() {
    let mut pending: Option<String> = Some(String::from("refresh"));
    let first: Option<String> = pending.take();
    assert_eq!(first.as_deref(), Some("refresh"));
    assert!(pending.is_none()); // take leaves None behind
    let second = pending.take();
    assert!(second.is_none());
    assert_eq!(second.unwrap_or_else(|| String::from("idle")), "idle");
}

#[derive(Debug, PartialEq)]
enum LevelError { NotAnInteger, OutOfRange }
fn parse_level(text: &str) -> Result<u8, LevelError> {
    let value = text.parse::<u8>().map_err(|_| LevelError::NotAnInteger)?;
    if (1..=5).contains(&value) { Ok(value) }
    else { Err(LevelError::OutOfRange) }
}
fn main() {
    assert_eq!(parse_level("3"), Ok(3));
    assert_eq!(parse_level("oops"), Err(LevelError::NotAnInteger));
    assert_eq!(parse_level("12"), Err(LevelError::OutOfRange));
    assert_eq!(parse_level("0"), Err(LevelError::OutOfRange));
}

