#include <assert.h>
#include <stdlib.h>
static void swap(int *a, int *b) {
    int saved = *a;
    *a = *b;
    *b = saved;
}
int main(void) {
    int left = 4, right = 9;
    swap(&left, &right);
    assert(left == 9 && right == 4);
    swap(&left, &left); // aliasing is harmless for this implementation
    assert(left == 9);
    return 0;
}

