static int sum(const int *values, size_t length) {
    int total = 0;
    for (size_t i = 0; i < length; ++i) total += values[i];
    return total;
}
int main(void) {
    const int samples[] = {2, 4, 6};
    const size_t length = sizeof samples / sizeof samples[0];
    assert(sum(samples, length) == 12);
