#include <string.h>
static int format_label(char *output, size_t capacity, const char *text) {
    return snprintf(output, capacity, "%s", text);
}
int main(void) {
    char label[5];
    int needed = format_label(label, sizeof label, "hello");
    assert(needed >= 0); // negative means an encoding error
    assert((size_t)needed >= sizeof label); // truncation occurred
    assert(strcmp(label, "hell") == 0);
    assert(label[sizeof label - 1] == '\0');
    needed = format_label(label, sizeof label, "tea");
    assert(needed == 3 && strcmp(label, "tea") == 0);
    return 0;
}

