#include <assert.h>
#include <stddef.h>
struct Scale { int factor; size_t calls; };
typedef int (*Transform)(int value, struct Scale *context);
static int multiply(int value, struct Scale *context) {
    context->calls += 1;
    return value * context->factor;
}
static void transform(int *values, size_t count, Transform fn,
                      struct Scale *context) {
    for (size_t i = 0; i < count; ++i) values[i] = fn(values[i], context);
}
int main(void) {
    int values[] = {2, 5, 8};
    struct Scale scale = { .factor = 3, .calls = 0 };
    transform(values, 3, multiply, &scale);
    assert(values[0] == 6 && values[1] == 15 && values[2] == 24);
    assert(scale.calls == 3);
    return 0;
}

#include <assert.h>
#include <stdbool.h>
enum Mode { MODE_READ = 1, MODE_WRITE = 2 };
static bool parse_mode(int raw, enum Mode *out) {
    switch (raw) {
    case MODE_READ: *out = MODE_READ; return true;
    case MODE_WRITE: *out = MODE_WRITE; return true;
    default: return false;
    }
}
int main(void) {
    enum Mode mode = MODE_READ;
    assert(parse_mode(2, &mode) && mode == MODE_WRITE);
    assert(!parse_mode(99, &mode));
    assert(mode == MODE_WRITE); // rejected input did not update the output
    return 0;
}

#include <assert.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <string.h>

int main(void) {
    char valid[sizeof(long) * CHAR_BIT + 2];
    int written = snprintf(valid, sizeof valid, "%ld", LONG_MAX);
    assert(written > 0 && (size_t)written < sizeof valid);
    char *end = NULL;
    errno = 0;
    long value = strtol(valid, &end, 10);
    int saved_error = errno; // capture before making unrelated calls
    assert(value == LONG_MAX && saved_error == 0 && *end == '\0');

    char too_large[sizeof(long) * CHAR_BIT + 2];
    memset(too_large, '9', sizeof too_large - 1);
    too_large[sizeof too_large - 1] = '\0';
    errno = 0;
    value = strtol(too_large, &end, 10);
    saved_error = errno;
    assert(value == LONG_MAX && saved_error == ERANGE && *end == '\0');
    return 0;
}

#include <assert.h>
#include <ctype.h>
#include <string.h>
static const char *skip_space(const char *text) {
    while (*text != '\0' && isspace((unsigned char)*text)) ++text;
    return text;
}
int main(void) {
    const char *text = " \t\nready";
    const char *trimmed = skip_space(text);
    assert(strcmp(trimmed, "ready") == 0);
    assert(strcmp(skip_space(""), "") == 0);
    assert(strcmp(skip_space("  \r"), "") == 0);
    return 0;
}

#include <assert.h>
#include <stdlib.h>
#define SQUARE(x) ((x) * (x))
static inline int square(int value) { return value * value; }
int main(void) {
    int next = 4;
    int result = square(next++); // increment evaluated exactly once
    assert(result == 16 && next == 5);
    assert(SQUARE(2 + 3) == 25); // macro parentheses handle precedence
    // Never call SQUARE(next++): it duplicates unsequenced side effects.
    return 0;
}

#include <assert.h>
#include <stdbool.h>
#include <limits.h>
static bool add_checked(int a, int b, int *out) {
    if (b > 0 && a > INT_MAX - b) return false;
    if (b < 0 && a < INT_MIN - b) return false;
    *out = a + b;
    return true;
}
int main(void) {
    int answer = 123;
    assert(add_checked(7, -3, &answer) && answer == 4);
    assert(!add_checked(INT_MAX, 1, &answer) && answer == 4);
    assert(!add_checked(INT_MIN, -1, &answer) && answer == 4);
    assert(add_checked(INT_MIN, INT_MAX, &answer) && answer == -1);
    return 0;
}

import json

def read_retries(text: str) -> int:
    data = json.loads(text)  # raises JSONDecodeError for invalid syntax
    if not isinstance(data, dict):
        raise ValueError("expected a JSON object")
    retries = data.get("retries")
    # bool is an int subclass, so isinstance(True, int) would be too broad.
    if type(retries) is not int or not 0 <= retries <= 5:
        raise ValueError("retries must be an integer from 0 to 5")
    return retries

assert read_retries('{"retries": 2}') == 2
for bad in ['[]', '{}', '{"retries": true}', '{"retries": 9}']:
    try:
        read_retries(bad)
    except ValueError:
        pass
    else:
        raise AssertionError("invalid data accepted")
try:
    read_retries('{broken')
except json.JSONDecodeError:
    pass
else:
    raise AssertionError("invalid JSON accepted")

from itertools import groupby
from operator import itemgetter

rows = [("tea", 2), ("water", 1), ("tea", 3)]
adjacent = [(key, list(group)) for key, group in groupby(rows, key=itemgetter(0))]
assert [key for key, _ in adjacent] == ["tea", "water", "tea"]
sorted_rows = sorted(rows, key=itemgetter(0))
totals = {
    key: sum(quantity for _, quantity in group)
    for key, group in groupby(sorted_rows, key=itemgetter(0))
}
assert totals == {"tea": 5, "water": 1}
assert rows[1] == ("water", 1)  # sorted made a new list

ExUnit.start()
defmodule ServingParser do
  def read(options) when is_map(options) do
    with {:ok, text} <- Map.fetch(options, "servings"),
         {:ok, number} <- parse_count(text) do
      {:ok, number}
    else
      :error -> {:error, :missing}
      {:error, reason} -> {:error, reason}
    end
  end
  defp parse_count(text) when is_binary(text) do
    case Integer.parse(text) do
      {number, ""} when number > 0 -> {:ok, number}
      _ -> {:error, :invalid_count}
    end
  end
  defp parse_count(_), do: {:error, :not_text}
end
defmodule ReferenceTest do
  use ExUnit.Case
  test "practical example" do
    assert ServingParser.read(%{"servings" => "3"}) == {:ok, 3}
    assert ServingParser.read(%{}) == {:error, :missing}
    assert ServingParser.read(%{"servings" => "oops"}) == {:error, :invalid_count}
    assert ServingParser.read(%{"servings" => 3}) == {:error, :not_text}
    assert ServingParser.read(%{"servings" => "3cups"}) == {:error, :invalid_count}
    assert ServingParser.read(%{"servings" => "0"}) == {:error, :invalid_count}
  end
end

