    try std.testing.expectEqual(@as(usize, 1), copy.edits);
    try std.testing.expectEqual(@as(u8, 9), original.bytes[0]);
}

const std = @import("std");
fn reverseFour(block: *[4]u8) void {
    std.mem.swap(u8, &block[0], &block[3]);
    std.mem.swap(u8, &block[1], &block[2]);
}
test "practical example" {
    var block: [4]u8 = .{ 10, 20, 30, 40 };
    reverseFour(&block);
    try std.testing.expectEqualSlices(u8, &.{ 40, 30, 20, 10 }, &block);
    const runtime_view: []const u8 = &block;
    try std.testing.expectEqual(@as(usize, 4), runtime_view.len);
}

const std = @import("std");
fn dropFirst(view: *[]u8) bool {
    if (view.*.len == 0) return false;
    view.* = view.*[1..];
    return true;
}
test "practical example" {
    var data: [3]u8 = .{ 7, 8, 9 };
    var remaining: []u8 = &data;
    try std.testing.expect(dropFirst(&remaining));
    try std.testing.expectEqual(@as(usize, 2), remaining.len);
    try std.testing.expectEqual(@as(u8, 8), remaining[0]);
    remaining[0] = 42;
    try std.testing.expectEqual(@as(u8, 42), data[1]);
    try std.testing.expect(dropFirst(&remaining));
    try std.testing.expect(dropFirst(&remaining));
    try std.testing.expect(!dropFirst(&remaining));
}

