const std = @import("std");
const Total = struct { sum: u32, calls: usize };
const Visitor = *const fn (*Total, u16) void;
fn accumulate(context: *Total, value: u16) void {
    context.sum += value;
    context.calls += 1;
}
fn visit(values: []const u16, context: *Total, callback: Visitor) void {
    for (values) |value| callback(context, value);
}
test "practical example" {
    var total: Total = .{ .sum = 0, .calls = 0 };
    const values: [3]u16 = .{ 2, 4, 6 };
    visit(&values, &total, &accumulate);
    try std.testing.expectEqual(@as(u32, 12), total.sum);
    try std.testing.expectEqual(@as(usize, 3), total.calls);
}

#!/usr/bin/env bash
set -euo pipefail
classify() {
  local number
  case "$1" in
    --help|-h) printf 'help\n' ;;
    --level=*)
      number=${1#--level=}
      case "$number" in
        ''|*[!0-9]*) return 2 ;;
      esac
      printf 'level:%s\n' "$number"
      ;;
    *) return 2 ;;
  esac
}
[[ $(classify -h) == help ]] || exit 1
[[ $(classify --level=07) == level:07 ]] || exit 1
if classify --level=oops; then exit 1; fi
if classify --level=; then exit 1; fi

fn main() {
    let mut names: Vec<String> = Vec::new();
    assert!(names.is_empty());
    assert_eq!(names.capacity(), 0);
    names.push(String::from("mint"));
    assert_eq!(names[0], "mint");
    let numbers = Vec::<u32>::new();
    assert_eq!(numbers.len(), 0);
}

fn main() {
    let mut batch: Vec<u32> = Vec::with_capacity(4);
    assert_eq!(batch.len(), 0);
    assert!(batch.capacity() >= 4);
    let initial_capacity = batch.capacity();
    for n in 0..4 { batch.push(n); }
    assert_eq!(batch, vec![0, 1, 2, 3]);
    assert_eq!(batch.capacity(), initial_capacity);
}

fn main() {
