    let mut taken = pending.pop().expect("the vector contains two items");
    taken.push('!'); // owns this String independently of pending
    assert_eq!(taken, "second!");
    assert_eq!(pending, vec!["first"]);
    assert_eq!(pending.pop().as_deref(), Some("first"));
    assert_eq!(pending.pop(), None);
}

