fn main() {
    let mut readings = vec![10_u32, 20];
    let current_len = readings.len();
    readings.reserve(6);
    assert_eq!(readings.len(), current_len);
    assert_eq!(readings, vec![10, 20]);
    assert!(readings.capacity() >= current_len + 6);
    let prepared = readings.capacity();
    for n in 0..6 { readings.push(n); }
    assert_eq!(readings.capacity(), prepared);
}

