use std::hash::{Hash, Hasher};
#[derive(Debug)]
struct Record { id: u32, label: &'static str }
impl PartialEq for Record { fn eq(&self, other: &Self) -> bool { self.id == other.id } }
impl Eq for Record {}
impl Hash for Record { fn hash<H: Hasher>(&self, state: &mut H) { self.id.hash(state); } }
fn main() {
    let mut records = HashSet::new();
    records.insert(Record { id: 7, label: "old" });
    let old = records.replace(Record { id: 7, label: "new" }).unwrap();
    assert_eq!(old.label, "old");
    assert_eq!(records.len(), 1);
    assert_eq!(records.iter().next().unwrap().label, "new");
}

