fn App() -> Html {
    let title = "Tea shelf";
    html! { <main><h1>{title}</h1><p>{"Choose a tea."}</p></main> }
}
fn main() { yew::Renderer::<App>::new().render(); }

use yew::prelude::*;
#[component]
fn App() -> Html {
    let enabled = use_state(|| false);
    let turn_on = {
        let enabled = enabled.clone();
        Callback::from(move |_| enabled.set(true))
    };
    html! {
        <div>
            <button onclick={turn_on}>{"Enable"}</button>
            <p>{if *enabled { "enabled" } else { "disabled" }}</p>
        </div>
    }
}
fn main() { yew::Renderer::<App>::new().render(); }

use yew::prelude::*;
#[derive(Properties, PartialEq)]
struct ChoiceProps { label: AttrValue, on_choose: Callback<String> }
#[component]
fn Choice(props: &ChoiceProps) -> Html {
    let on_choose = props.on_choose.clone();
    let label = props.label.to_string();
    let onclick = Callback::from(move |_| on_choose.emit(label.clone()));
    html! { <button {onclick}>{props.label.clone()}</button> }
}
#[component]
fn App() -> Html {
    let chosen = use_state(String::new);
    let on_choose = { let chosen = chosen.clone(); Callback::from(move |s: String| chosen.set(s)) };
    html! { <><Choice label="mint" {on_choose}/><p>{(*chosen).clone()}</p></> }
}
fn main() { yew::Renderer::<App>::new().render(); }

use dioxus::prelude::*;
fn app() -> Element {
    rsx! { main { h1 { "Tea shelf" } p { "Choose a tea." } } }
}
fn main() { dioxus::launch(app); }

use dioxus::prelude::*;
fn app() -> Element {
    let mut enabled = use_signal(|| false);
    rsx! {
        button { onclick: move |_| enabled.set(true), "Enable" }
        p { "Enabled: {enabled}" }
    }
}
fn main() { dioxus::launch(app); }

use dioxus::prelude::*;
#[component]
fn Choice(label: String, on_choose: EventHandler<String>) -> Element {
    let selected = label.clone();
    rsx! { button { onclick: move |_| on_choose.call(selected.clone()), "{label}" } }
}
fn app() -> Element {
    let mut selected = use_signal(String::new);
    rsx! {
        Choice { label: "mint".to_string(), on_choose: move |name| selected.set(name) }
        p { "Selected: {selected}" }
    }
}
fn main() { dioxus::launch(app); }
